const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Lynx Mountain, Washington (approximate location) and border region
  const firePoint = ee.Geometry.Point([-119.5, 48.5]); // Northeast WA
  // Create a buffer area crossing into British Columbia
  const bcBorderRegion = ee.Geometry.Rectangle([-120.5, 48.8, -118.5, 49.5]);

  const targetDate = '2025-09-13';
  const dateRange = ee.DateRange(targetDate, ee.Date(targetDate).advance(1, 'day'));

  // 2. Data Acquisition - Use VIIRS/S-NPP for smoke detection
  // VIIRS I-band at 375m has good smoke detection capability
  let viirsCol = ee.ImageCollection('NOAA/VIIRS/001/VNP09GA')
    .filterBounds(firePoint)
    .filterDate(dateRange);

  const viirsSize = viirsCol.size().getInfo();
  console.log(`VIIRS Images for ${targetDate}: ${viirsSize}`);

  // If no VIIRS, try MODIS Aqua as fallback
  if (viirsSize === 0) {
    viirsCol = ee.ImageCollection('MODIS/061/MYD09GA')
      .filterBounds(firePoint)
      .filterDate(dateRange);
    const modisSize = viirsCol.size().getInfo();
    console.log(`MODIS Aqua Images for ${targetDate}: ${modisSize}`);
    if (modisSize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // 3. Processing - Use NIR/SWIR bands for smoke detection
  // For VIIRS: M11 (2.25µm) and M10 (1.61µm) or I2 (0.865µm)
  // For MODIS: band 7 (2.1µm) and band 2 (0.86µm)
  const img = viirsCol.first();

  // Simple smoke detection: High reflectance in SWIR, moderate in NIR
  // Normalized Difference Smoke Index (NDSI) = (SWIR - NIR) / (SWIR + NIR)
  // Smoke typically has NDSI > 0.1 to 0.3

  // Try different band combinations based on sensor
  let swirBand, nirBand;
  const collectionId = img.get('system:index').getInfo();

  if (collectionId.includes('VNP')) {
    // VIIRS bands
    swirBand = 'M11'; // 2.25µm
    nirBand = 'I2';   // 0.865µm
  } else {
    // MODIS bands
    swirBand = 'sur_refl_b07'; // 2.1µm
    nirBand = 'sur_refl_b02';  // 0.86µm
  }

  // Check if bands exist
  const bands = img.bandNames().getInfo();
  if (!bands.includes(swirBand) || !bands.includes(nirBand)) {
    console.log("Required bands not found");
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate NDSI
  const swir = img.select(swirBand).multiply(0.0001); // Scale factor
  const nir = img.select(nirBand).multiply(0.0001);
  const ndsi = swir.subtract(nir).divide(swir.add(nir));

  // Mask clouds using QA bands
  // For VIIRS: 'QF1' bitmask, for MODIS: 'StateQA'
  let cloudMask;
  if (collectionId.includes('VNP')) {
    // VIIRS cloud mask - bits 0-1 for cloud state
    const qf1 = img.select('QF1');
    cloudMask = qf1.bitwiseAnd(3).eq(0); // Clear or probably clear
  } else {
    // MODIS cloud mask - StateQA bits 0-1
    const stateQA = img.select('StateQA');
    cloudMask = stateQA.bitwiseAnd(3).lt(2); // Clear or cloudy
  }

  const masked = ndsi.updateMask(cloudMask);

  // 4. Calculate pixel counts
  const bcRegionStats = masked.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bcBorderRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const pixelCount = bcRegionStats[Object.keys(bcRegionStats)[0]];
  console.log(`Valid pixels in BC border region: ${pixelCount}`);

  if (pixelCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Count smoke pixels (NDSI > 0.15 threshold)
  const smokePixels = masked.gt(0.15).reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: bcBorderRegion,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const smokeCount = smokePixels[Object.keys(smokePixels)[0]];
  console.log(`Smoke pixels (NDSI>0.15) in BC: ${smokeCount}`);

  // 5. Validation & Final Answer
  if (smokeCount === undefined || smokeCount === null) {
    console.log("<answer>C3</answer>");
  } else if (smokeCount > 10) { // Threshold: at least 10 smoke pixels
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
